        e instanceof HttpErrorResponse && e.status === 423
          ? CLOSED
          : e instanceof HttpErrorResponse && e.status === 422
          ? RETIRED
          : e instanceof HttpErrorResponse && e.status === 400 && correction
          ? CORRECTION
          : id === null ? 'Could not add that claim.' : 'Could not save that claim.',
      );
    } finally {
      this.saving = false;
    }
